from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject
from taf.gnb.oam.coam.vdu.schemas.asm.alarms import Alarm
from taf.gnb.oam.coam.vdu.schemas.asm.dist_names import DistNames


class RmodConnector(SchemaObject):
    rmod_id = SchemaField(name='rmod_id', optional=True)
    rmod_r_id = SchemaField(name='rmod_r_id', optional=True)
    rmod_type = SchemaField(name='rmod_type', optional=True)
    port_name = SchemaField(name='port_name', optional=True)
    local_cells = SchemaField(name='local_cells', many=True, optional=True)

    def __init__(self, rmod_id, rmod_r_id, rmod_type, port_name, local_cells):
        self.rmod_id = rmod_id
        self.rmod_r_id = rmod_r_id
        self.rmod_type = rmod_type
        self.port_name = port_name
        self.local_cells = local_cells

        super(RmodConnector, self).__init__()


class VduAldBasic(SchemaObject):
    id = SchemaField(name='id', not_null=True)
    configuration_id = SchemaField(name='configuration_id', optional=True)
    product_code = SchemaField(name='product_code', optional=True)
    serial_number = SchemaField(name='serial_number', optional=True)
    vendor_code = SchemaField(name='vendor_code', optional=True)
    software_version = SchemaField(name='software_version', optional=True)
    hardware_version = SchemaField(name='hardware_version', optional=True)
    control_protocol = SchemaField(name='control_protocol', optional=True)
    aisg_protocol_version = SchemaField(name='aisg_protocol_version', optional=True)
    release_id3_gpp = SchemaField(name='release_id3_gpp', optional=True)
    control_ports = SchemaField(name='control_ports', many=True, klass=RmodConnector, optional=True)
    availability_status = SchemaField(name='availability_status', optional=True)
    operational_state = SchemaField(name='operational_state', optional=True)
    procedural_status = SchemaField(name='procedural_status', optional=True)
    alarms = SchemaField(name='alarms', many=True, klass=Alarm, optional=True)
    dist_names = SchemaField(name='dist_names', klass=DistNames, optional=True)

    def __init__(self, id, configuration_id, product_code, serial_number, vendor_code, software_version,
                 hardware_version, control_protocol, aisg_protocol_version, release_id3_gpp, control_ports,
                 availability_status, operational_state, procedural_status, alarms, dist_names):
        self.id = id
        self.configuration_id = configuration_id
        self.product_code = product_code
        self.serial_number = serial_number
        self.vendor_code = vendor_code
        self.software_version = software_version
        self.hardware_version = hardware_version
        self.control_protocol = control_protocol
        self.aisg_protocol_version = aisg_protocol_version
        self.release_id3_gpp = release_id3_gpp
        self.control_ports = control_ports
        self.availability_status = availability_status
        self.operational_state = operational_state
        self.procedural_status = procedural_status
        self.alarms = alarms
        self.dist_names = dist_names

        super(VduAldBasic, self).__init__()


class VduAldState(VduAldBasic):
    is_vet_device = SchemaField(name='is_vet_device')
    dc_power_sources = SchemaField(name='dc_power_sources', many=True, klass=RmodConnector, not_null=True)

    def __init__(self, id, configuration_id, product_code, serial_number, vendor_code, software_version,
                 hardware_version, control_protocol, aisg_protocol_version, release_id3_gpp, control_ports,
                 availability_status, operational_state, procedural_status, alarms, dist_names, is_vet_device,
                 dc_power_sources):
        self.id = id
        self.configuration_id = configuration_id
        self.product_code = product_code
        self.serial_number = serial_number
        self.vendor_code = vendor_code
        self.software_version = software_version
        self.hardware_version = hardware_version
        self.control_protocol = control_protocol
        self.aisg_protocol_version = aisg_protocol_version
        self.release_id3_gpp = release_id3_gpp
        self.control_ports = control_ports
        self.availability_status = availability_status
        self.operational_state = operational_state
        self.procedural_status = procedural_status
        self.alarms = alarms
        self.dist_names = dist_names
        self.is_vet_device = is_vet_device
        self.dc_power_sources = dc_power_sources

        super(VduAldState, self).__init__(id, configuration_id, product_code, serial_number, vendor_code,
                                          software_version, hardware_version, control_protocol, aisg_protocol_version,
                                          release_id3_gpp, control_ports, availability_status, operational_state,
                                          procedural_status, alarms, dist_names)


class AntennaInfo(SchemaObject):
    ant_model = SchemaField(name='ant_model', optional=True)
    ant_serial = SchemaField(name='ant_serial', optional=True)
    ant_bearing = SchemaField(name='ant_bearing', optional=True)
    install_date = SchemaField(name='install_date', optional=True)
    installer_id = SchemaField(name='installer_id', optional=True)
    base_station_id = SchemaField(name='base_station_id', optional=True)
    sector_id = SchemaField(name='sector_id', optional=True)

    def __init__(self, ant_model, ant_serial, ant_bearing, install_date, installer_id, base_station_id, sector_id):
        self.ant_model = ant_model
        self.ant_serial = ant_serial
        self.ant_bearing = ant_bearing
        self.install_date = install_date
        self.installer_id = installer_id
        self.base_station_id = base_station_id
        self.sector_id = sector_id

        super(AntennaInfo, self).__init__()


class RETUState(SchemaObject):
    id = SchemaField(name='id', not_null=True)
    configuration_id = SchemaField(name='configuration_id', optional=True)
    angle = SchemaField(name='angle', optional=True)
    subunit_number = SchemaField(name='subunit_number', optional=True)
    user_note1 = SchemaField(name='user_note1', optional=True)
    user_note2 = SchemaField(name='user_note2', optional=True)
    mechanical_angle = SchemaField(name='mechanical_angle', optional=True)
    min_angle = SchemaField(name='min_angle', optional=True)
    max_angle = SchemaField(name='max_angle', optional=True)
    antenna_list = SchemaField(name='antenna_list', klass=RmodConnector, many=True, not_null=True)
    antenna_info = SchemaField(name='antenna_info', klass=AntennaInfo, optional=True)
    availability_status = SchemaField(name='availability_status', optional=True)
    operational_state = SchemaField(name='operational_state', optional=True)
    procedural_status = SchemaField(name='procedural_status', optional=True)
    alarms = SchemaField(name='alarms', klass=Alarm, not_null=True, many=True)
    dist_names = SchemaField(name='dist_names', not_null=True, klass=DistNames)

    def __init__(self, id, alarms, angle, subunit_number, user_note1, user_note2, min_angle, max_angle,
                 antenna_info, antenna_list, configuration_id, dist_names, mechanical_angle,
                 availability_status, operational_state, procedural_status):
        self.id = id
        self.alarms = alarms
        self.antenna_info = antenna_info
        self.antenna_list = antenna_list
        self.configuration_id = configuration_id
        self.dist_names = dist_names
        self.mechanical_angle = mechanical_angle
        self.availability_status = availability_status
        self.operational_state = operational_state
        self.procedural_status = procedural_status
        self.angle = angle
        self.subunit_number = subunit_number
        self.user_note1 = user_note1
        self.user_note2 = user_note2
        self.min_angle = min_angle
        self.max_angle = max_angle

        super(RETUState, self).__init__()


class GetRETsDiffV1(SchemaObject):
    id = SchemaField(name='id', not_null=True)
    ald = SchemaField(name='ald', not_null=True, klass=VduAldState)
    subunits = SchemaField(name='subunits', not_null=True, klass=RETUState, many=True)

    def __init__(self, id, ald, subunits):
        self.id = id
        self.ald = ald
        self.subunits = subunits

        super(GetRETsDiffV1, self).__init__()
